
window.VSim=window.VSim||{};(function(NS){const KEY='village-observer-v0-7';function dl(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){const r=localStorage.getItem(KEY);return r?NS.World.from(JSON.parse(r)):null;},export(w){dl(`village-observer-v07-save-${w.year}y.json`,JSON.stringify(w.serialize(),null,2));},exportDevJSON(w){dl(`village-observer-v07-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w),null,2));},exportDevCSV(w){dl(`village-observer-v07-snapshots-${w.telemetry.sessionId}.csv`,'\ufeff'+w.telemetry.snapshotsCSV(),'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));}};})(window.VSim);

